def transform(grid):
    h,w=len(grid),len(grid[0]); seen=set(); boxes=[]
    for r in range(h):
        for c in range(w):
            if grid[r][c]!=0 or (r,c) in seen: continue
            stack=[(r,c)]; seen.add((r,c)); cells=[]
            while stack:
                y,x=stack.pop(); cells.append((y,x))
                for yy,xx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
                    if 0<=yy<h and 0<=xx<w and grid[yy][xx]==0 and (yy,xx) not in seen:
                        seen.add((yy,xx)); stack.append((yy,xx))
            a=min(y for y,x in cells); b=max(y for y,x in cells); l=min(x for y,x in cells); z=max(x for y,x in cells)
            if b-a>=2 and z-l>=2: boxes.append((a,l,b,z))
    boxes=[q for q in boxes if not any(p!=q and p[0]<=q[0] and p[1]<=q[1] and p[2]>=q[2] and p[3]>=q[3] for p in boxes)]
    boxes.sort()
    patches=[[row[l+1:z] for row in grid[a+1:b]] for a,l,b,z in boxes]
    if not patches:return []
    return [sum((p[i] for p in patches if i<len(p)),[]) for i in range(max(map(len,patches)))]

